// BUG: cyclic banks break pointer-cast / sequential index mapping
#pragma HLS ARRAY_PARTITION variable=pool_window cyclic factor=2
// FIX: match access pattern
#pragma HLS ARRAY_PARTITION variable=pool_window complete

// BUG: partitioning the wrong dimension for column-parallel access
#pragma HLS ARRAY_PARTITION variable=A cyclic factor=8 dim=1
// FIX: partition the dimension used by the parallel index
#pragma HLS ARRAY_PARTITION variable=A cyclic factor=8 dim=2

// BUG: factor 5 does not divide size 16
#pragma HLS ARRAY_PARTITION variable=A cyclic factor=5 dim=2
// FIX: use a divisor of the dimension (e.g. 2/4/8)
#pragma HLS ARRAY_PARTITION variable=A cyclic factor=4 dim=2

// BAD
for (i) { #pragma HLS PIPELINE II=1
  for (j) { ... } }
// GOOD
for (i) {
  for (j) { #pragma HLS PIPELINE II=1
    ... } }
